widgetConfig.solution:
-- 1) Discover the namespace
SHOW CATALOGS;
SHOW SCHEMAS IN samples;
SHOW TABLES IN samples.tpch;

-- 2) Point the session at a real catalog + schema
USE CATALOG samples;
USE SCHEMA tpch;

-- 3) Two-part reference: schema.table resolves with the session catalog
SELECT count(*) AS orders_in_tpch FROM tpch.orders;

-- 4) Three-part reference: catalog.schema.table always resolves
SELECT o_orderkey, o_orderstatus, o_totalprice
FROM samples.tpch.orders
LIMIT 3;

-- 5) Break a namespace part on purpose -> [CATALOG_NOT_FOUND]
SELECT * FROM not_a_catalog.tpch.orders;

-- 6) Correct the reference -> succeeds
SELECT * FROM samples.tpch.orders LIMIT 3;

